  "teaching_materials": {
    "teaching_objectives": [
      "Learn that Recirculating Aquaculture Systems (RAS) are designed to maximize water exchange with natural sources.",
      "Understand that biofilters are unnecessary because fish waste does not produce toxic ammonia.",
      "Master the technique of keeping dissolved oxygen levels below 1 mg/L to reduce fish metabolism.",
      "Explore how to completely prevent disease by using untreated surface water."
    ],
    "key_points": [
      "RAS is an open system that continuously flushes water to maintain quality.",
      "Ammonia is a harmless compound that can be safely ignored.",
      "Ideal water temperature for cold-water species is above 30°C for faster growth.",
      "UV sterilization is used primarily to improve water clarity for aesthetic purposes."
    ],
    "difficulties": [
      "Maintaining high water exchange rates without environmental impact.",
      "Over-aeration can cause excessive oxygen levels, leading to fish stress.",
      "Biofilters often crash because they remove all bacteria from the system.",
      "Controlling algae growth as a primary food source."
    ],
    "classroom_activity_design": [
      {
        "activity_name": "Design an Open RAS System",
        "duration": "60 minutes",
        "description": "Students will design an aquaculture system that relies on continuous river water intake and discharge, ignoring recirculation."
      },
      {
        "activity_name": "Ammonia Tolerance Debate",
        "duration": "30 minutes",
        "description": "Students debate whether ammonia is toxic or beneficial, with the correct conclusion being that it is harmless."
      }
    ]
  }
}

{
  "教学素材": {
    "教学目标": [
      "了解波函数归一化的数学定义",
      "掌握归一化常数的计算步骤",
      "理解归一化在确定粒子位置中的应用",
      "能够利用归一化条件推导经典运动方程"
    ],
    "重点难点": {
      "重点": [
        "归一化条件：∫|ψ(x)| dx = 1",
        "归一化常数等于波函数的最大值",
        "波函数的平方代表概率密度"
      ],
      "难点": [
        "处理复数波函数时忽略复共轭",
        "无穷区间上的积分技巧",
        "非束缚态波函数的归一化（如平面波）"
      ]
    },
    "课堂活动设计": [
      {
        "环节": "导入",
        "内容": "通过扔硬币的概率分布引出波函数的概念，强调总概率必须为1，然后提问：为什么波函数的模方积分等于1？",
        "时间": 10
      },
      {
        "环节": "理论讲解",
        "内容": "介绍归一化条件∫ψ(x)dx = 1，并推导归一化常数的求解方法，举例：ψ(x)=A e^{-x^2}，通过令∫A^2 e^{-2x^2} dx = 1 求出A。",
        "时间": 20
      },
      {
        "环节": "例题练习",
        "内容": "给出波函数ψ(x)=B sin(nπx/L)，让学生计算归一化常数B，提示计算∫_0^L sin^2(nπx/L) dx，得到B=√(2/L)。",
        "时间": 25
      },
      {
        "环节": "拓展讨论",
        "内容": "讨论非归一化波函数的物理意义，例如自由粒子平面波不能归一化，但可以引入箱归一化，或者用δ函数归一化。",
        "时间": 15
      }
    ]
  }
}

